import { createRoot } from 'react-dom/client'
import App from './App.tsx'
import './index.css'
import { initTelemetry } from '@/shared/lib/telemetry/telemetry'
import { initMetrics } from '@/shared/lib/telemetry/metrics'
import { initRum } from '@/shared/lib/telemetry/rum'
import { initWideEvents } from '@/shared/lib/telemetry/wide-events'

// Inicializa telemetria antes de renderizar a app.
// Quando VITE_OTEL_ENABLED=false, todas as init retornam NOOPs — zero overhead.
async function bootstrap() {
  try {
    await initTelemetry();
    await initMetrics();
    await initRum();
    await initWideEvents();
  } catch (error) {
    console.error('[Telemetry Init Error]', error);
  }

  createRoot(document.getElementById("root")!).render(<App />);
}

bootstrap();

