import VerificacaoPerdas from "./pages/VerificacaoPerdas";
import Marketing from "./pages/Marketing";
import GerenciarProdutosMaster from "./pages/GerenciarProdutosMaster";
import FichasTecnicas from "./pages/producao/FichasTecnicas";
import RecipeConfigurator from "./pages/producao/RecipeConfigurator";
import CmvPage from "./features/financeiro/ui/Cmv.page";
import CmvConfiguratorPage from "./features/financeiro/ui/CmvConfigurator.page";
import Insumos from "./pages/producao/Insumos";
import AdminDashboard from "./features/admin/ui/AdminDashboard.page";
import { MiaInlineChat } from "./features/mia/ui/MiaInlineChat";
import { MiaOutcomesDashboard } from "./features/mia/ui/MiaOutcomesDashboard";
import MiaHealthDashboard from "./features/mia/ui/MiaHealthDashboard";
import MiaObservabilityDashboard from "./features/mia/ui/MiaObservabilityDashboard";
import MiaPatternsDashboard from "./features/mia/ui/MiaPatternsDashboard";
