                    />
                    <Route
                      path="/etiquetas"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <LabelPrinting />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/lotes/rastreabilidade"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <BatchTraceability />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/etiquetas/auditoria"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <EtiquetaAuditoria />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/logistica/containers-abertos"
                      element={
                        <ProtectedRoute>
                          <ContainersAbertos />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/etiquetas/auditoria-eventos"
                      element={
                        <ProtectedRoute>
                          <EventosAuditoria />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/etiquetas/:uid"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <EtiquetaTimeline />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/logistica/separacao-bip/:sessionId"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <SeparacaoBipPage />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/logistica/recebimento"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <RecebimentoBip />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/scanner"
                      element={
                        <ProtectedRoute>
                          <Scanner />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/produtos"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Produtos />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/produtos/analytics"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <ProductAnalytics />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/requisicao"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Requisicao />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/agente-repa"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Requisicao />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/requisicao-conclusao"
                      element={
                        <ProtectedRoute>
