  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/shared/ui/table';

import { CATEGORIAS_OUVIDORIA, STATUS_OUVIDORIA } from '../lib/categorias';
import { LOJAS_OUVIDORIA, nomeLoja } from '../lib/lojas';
import { useOuvidoriaAccess } from '../model/useOuvidoriaAccess';
import { useOuvidoriaList } from '../model/useOuvidoriaList';
import { useOuvidoriaUnreadCount } from '../model/useOuvidoriaUnreadCount';
import { StatusBadge } from './StatusBadge';
import { CategoriaBadge } from './CategoriaBadge';
import type { CategoriaOuvidoria, DenunciaOuvidoria, OuvidoriaFiltros, StatusOuvidoria } from '../types';

// ---------------------------------------------------------------------------
// Componente de KPI card
// ---------------------------------------------------------------------------

interface KpiCardProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  highlight?: boolean;
}

function KpiCard({ icon, label, value, highlight }: KpiCardProps) {
  return (
    <div className="relative group bg-white/60 dark:bg-[#1A1A1A]/60 rounded-[2rem] p-5 border border-[#57715B]/10 shadow-sm hover:shadow-md backdrop-blur-md transition-all overflow-hidden">
      <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity pointer-events-none">
        <div className="h-12 w-12 text-[#57715B]">{icon}</div>
      </div>
      <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
        {label}
      </p>
      <p
        className={`text-2xl font-bold tabular-nums ${
          highlight ? 'text-amber-600' : 'text-[#2D362E] dark:text-[#E6DCCF]'
        }`}
      >
        {value}
      </p>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Skeleton de carregamento
// ---------------------------------------------------------------------------

function SkeletonPainel() {
  return (
    <MommaPageLayout>
      <div className="p-4 md:p-6 flex flex-col gap-6">
        <div className="h-12 w-64 rounded-2xl bg-[#57715B]/5 animate-pulse" />
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="h-24 rounded-[2rem] bg-[#57715B]/5 animate-pulse" />
          ))}
        </div>
        <div className="h-64 rounded-2xl bg-[#57715B]/5 animate-pulse" />
      </div>
    </MommaPageLayout>
  );
}

// ---------------------------------------------------------------------------
// Componente interno do painel (já autenticado)
// ---------------------------------------------------------------------------

function PainelOuvidoria() {
  const navigate = useNavigate();
  const [filtros, setFiltros] = useState<OuvidoriaFiltros>({});
  const [mostrarFiltros, setMostrarFiltros] = useState(false);

  const { canView } = useOuvidoriaAccess();
  const { data: unread } = useOuvidoriaUnreadCount(canView);
  const { data: denuncias = [], isLoading } = useOuvidoriaList(filtros);

  const totalPorStatus = (status: StatusOuvidoria) =>
    denuncias.filter((d) => d.status === status).length;

  const temFiltros = Boolean(filtros.status || filtros.categoria || filtros.lojaId !== undefined);

  const limparFiltros = () => setFiltros({});

  return (
    <div className="p-4 md:p-6 flex flex-col gap-6 max-w-7xl mx-auto w-full">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="rounded-2xl bg-[#57715B]/10 p-3 flex-shrink-0">
          <Shield className="h-6 w-6 text-[#57715B]" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <h1 className="text-2xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
              Ouvidoria
            </h1>
            {unread && unread.total > 0 && (
              <span className="inline-flex items-center rounded-full bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800/30 px-2.5 py-0.5 text-xs font-semibold text-amber-600">
                {unread.total} não {unread.total === 1 ? 'lida' : 'lidas'}
              </span>
            )}
          </div>
          <p className="text-xs uppercase tracking-widest text-muted-foreground">
            Canal anônimo de denúncias · acesso restrito
          </p>
        </div>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
        <KpiCard icon={<Inbox />} label="Total" value={denuncias.length} />
        <KpiCard icon={<AlertCircle />} label="Novas" value={totalPorStatus('recebida')} highlight={totalPorStatus('recebida') > 0} />
        <KpiCard icon={<Filter />} label="Em análise" value={totalPorStatus('em_analise')} />
        <KpiCard icon={<CheckCircle2 />} label="Resolvidas" value={totalPorStatus('resolvida')} />
      </div>

      {/* Filtros */}
      <GlassCard className="p-4">
        <div className="flex items-center justify-between mb-3">
          <button
            type="button"
            onClick={() => setMostrarFiltros((v) => !v)}
            className="flex items-center gap-1.5 text-sm font-medium text-[#57715B] hover:text-[#465b49] transition-colors"
          >
            <Filter className="h-4 w-4" />
            Filtros
            {temFiltros && (
              <span className="inline-flex items-center justify-center h-4 w-4 rounded-full bg-[#57715B] text-white text-[10px] font-bold">
                !
              </span>
            )}
          </button>
          {temFiltros && (
            <button
              type="button"
              onClick={limparFiltros}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-red-500 transition-colors"
            >
              <X className="h-3.5 w-3.5" />
              Limpar filtros
            </button>
          )}
        </div>

        {mostrarFiltros && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 pt-2 border-t border-[#57715B]/10">
            {/* Status */}
            <div className="flex flex-col gap-1">
              <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Status
              </label>
              <Select
                value={filtros.status ?? '__todos'}
                onValueChange={(v) =>
                  setFiltros((f) => ({
                    ...f,
                    status: v === '__todos' ? undefined : (v as StatusOuvidoria),
                  }))
                }
              >
                <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-9 text-sm">
                  <SelectValue placeholder="Todos" />
                </SelectTrigger>
                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
                  <SelectItem value="__todos">Todos os status</SelectItem>
                  {STATUS_OUVIDORIA.map((s) => (
                    <SelectItem key={s.value} value={s.value}>
                      {s.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Categoria */}
            <div className="flex flex-col gap-1">
              <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Categoria
              </label>
              <Select
                value={filtros.categoria ?? '__todas'}
                onValueChange={(v) =>
                  setFiltros((f) => ({
                    ...f,
                    categoria: v === '__todas' ? undefined : (v as CategoriaOuvidoria),
                  }))
                }
              >
                <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-9 text-sm">
                  <SelectValue placeholder="Todas" />
                </SelectTrigger>
                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
                  <SelectItem value="__todas">Todas as categorias</SelectItem>
                  {CATEGORIAS_OUVIDORIA.map((c) => (
                    <SelectItem key={c.value} value={c.value}>
                      {c.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Loja */}
            <div className="flex flex-col gap-1">
              <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Loja
              </label>
              <Select
                value={filtros.lojaId !== undefined ? String(filtros.lojaId) : '__todas'}
                onValueChange={(v) =>
                  setFiltros((f) => ({
                    ...f,
                    lojaId: v === '__todas' ? undefined : parseInt(v, 10),
                  }))
                }
              >
                <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-9 text-sm">
                  <SelectValue placeholder="Todas" />
                </SelectTrigger>
                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
                  <SelectItem value="__todas">Todas as lojas</SelectItem>
                  {LOJAS_OUVIDORIA.map((l) => (
                    <SelectItem key={l.id} value={String(l.id)}>
                      {l.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        )}
      </GlassCard>

      {/* Lista */}
      {isLoading ? (
        <div className="flex flex-col gap-2">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-16 rounded-2xl bg-[#57715B]/5 animate-pulse" />
          ))}
        </div>
      ) : denuncias.length === 0 ? (
        <div className="flex flex-col items-center gap-3 py-16 text-center">
          <Archive className="h-10 w-10 text-[#57715B]/30" />
          <p className="text-sm text-muted-foreground">
            {temFiltros ? 'Nenhuma denúncia encontrada com esses filtros' : 'Nenhuma denúncia registrada'}
          </p>
          {temFiltros && (
            <Button
              variant="ghost"
              size="sm"
              onClick={limparFiltros}
              className="hover:bg-[#57715B]/10 text-[#57715B] rounded-xl"
            >
              Limpar filtros
            </Button>
          )}
        </div>
      ) : (
        <>
          {/* Desktop: tabela */}
          <div className="hidden md:block overflow-x-auto rounded-2xl border border-[#57715B]/10 shadow-sm">
            <Table>
              <TableHeader>
                <TableRow className="bg-[#57715B]/5 border-b border-[#57715B]/10 hover:bg-[#57715B]/5">
                  <TableHead className="text-xs font-semibold uppercase tracking-wider text-muted-foreground w-44">
                    Protocolo
                  </TableHead>
                  <TableHead className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Categoria
                  </TableHead>
                  <TableHead className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Loja
                  </TableHead>
                  <TableHead className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Data
                  </TableHead>
                  <TableHead className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Status
                  </TableHead>
                  <TableHead className="w-8" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {denuncias.map((d) => (
                  <TableRow
                    key={d.id}
                    className="hover:bg-white/80 dark:hover:bg-[#1A1A1A]/80 cursor-pointer border-b border-[#57715B]/5 transition-colors"
                    onClick={() => navigate(`/ouvidoria/${d.id}`)}
                  >
                    <TableCell>
                      <div className="flex items-center gap-1.5">
                        {d.status === 'recebida' && (
                          <Dot className="h-5 w-5 text-amber-500 flex-shrink-0 -ml-1" />
                        )}
                        <span className="font-mono text-sm font-semibold text-[#57715B]">
                          {d.protocolo}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <CategoriaBadge categoria={d.categoria} />
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {nomeLoja(d.loja_id)}
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground whitespace-nowrap">
                      {format(parseISO(d.created_at), 'dd/MM/yyyy', { locale: ptBR })}
                    </TableCell>
                    <TableCell>
                      <StatusBadge status={d.status} />
                    </TableCell>
                    <TableCell>
                      <Lock className="h-3.5 w-3.5 text-muted-foreground/40" />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>

          {/* Mobile: cards */}
          <div className="flex flex-col gap-3 md:hidden">
            {denuncias.map((d) => (
              <button
                key={d.id}
                type="button"
                onClick={() => navigate(`/ouvidoria/${d.id}`)}
                className="w-full text-left"
              >
                <GlassCard className="p-4 hover:shadow-md transition-shadow">
                  <div className="flex items-start justify-between gap-2 mb-2">
                    <div className="flex items-center gap-1.5 min-w-0">
                      {d.status === 'recebida' && (
                        <Dot className="h-5 w-5 text-amber-500 flex-shrink-0 -ml-1" />
                      )}
                      <span className="font-mono text-sm font-bold text-[#57715B] truncate">
                        {d.protocolo}
                      </span>
                    </div>
                    <StatusBadge status={d.status} />
                  </div>
                  <div className="flex flex-wrap items-center gap-2 mt-1">
                    <CategoriaBadge categoria={d.categoria} />
                    <span className="text-xs text-muted-foreground">{nomeLoja(d.loja_id)}</span>
                    <span className="text-xs text-muted-foreground">
                      {format(parseISO(d.created_at), 'dd/MM/yyyy', { locale: ptBR })}
                    </span>
                  </div>
                </GlassCard>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Página exportada com gate de acesso
// ---------------------------------------------------------------------------

function OuvidoriaComGate() {
  const { canView, isLoading } = useOuvidoriaAccess();

  if (isLoading) return <SkeletonPainel />;

  if (!canView) {
    return (
      <MommaPageLayout>
        <div className="flex items-center justify-center min-h-[60vh] p-6">
          <GlassCard variant="premium" className="p-8 max-w-sm w-full flex flex-col items-center gap-4 text-center">
            <div className="rounded-2xl bg-[#57715B]/10 p-4">
              <Lock className="h-8 w-8 text-[#57715B]" />
            </div>
            <h2 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              Acesso restrito a proprietárias
            </h2>
            <p className="text-sm text-muted-foreground">
              O painel de ouvidoria é acessível apenas às proprietárias da Momma. Entre em
              contato se acredita que deveria ter acesso.
            </p>
          </GlassCard>
        </div>
      </MommaPageLayout>
    );
  }

  return (
    <MommaPageLayout>
      <PainelOuvidoria />
    </MommaPageLayout>
  );
}

export default function OuvidoriaPage() {
  return (
    <TelemetryErrorBoundary moduleName="ouvidoria">
      <OuvidoriaComGate />
    </TelemetryErrorBoundary>
  );
}

