162	
163	        {/* Callout de atenção */}
164	        <div className="rounded-2xl border border-amber-200 dark:border-amber-800/30 bg-amber-50 dark:bg-amber-900/10 p-4 flex gap-3">
165	          <Shield className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
166	          <div className="text-sm text-amber-700 dark:text-amber-400">
167	            <p className="font-semibold mb-1">Guarde o protocolo e a senha</p>
168	            <p>
169	              Esses dados são a <strong>única forma</strong> de acompanhar sua denúncia.
170	              Não há recuperação de senha. Recomendamos anotar em local seguro.
171	            </p>
172	          </div>
173	        </div>
174	
175	        {/* Ação: acompanhar */}
176	        <Button
177	          type="button"
178	          onClick={() => onAcompanhar(protocolo)}
179	          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
180	        >
181	          Acompanhar denúncia
182	          <ChevronRight className="h-4 w-4" />
183	        </Button>
184	      </div>
185	    );
186	  }
187	
188	  return (
189	    <form onSubmit={onSubmit} className="flex flex-col gap-5">
190	      {/* Callout de anonimato */}
191	      <div className="rounded-2xl border border-[#57715B]/20 bg-[#57715B]/5 p-4 flex gap-3">
192	        <Lock className="h-5 w-5 text-[#57715B] flex-shrink-0 mt-0.5" />
193	        <p className="text-sm text-[#57715B] dark:text-[#8FAE94]">
194	          Sua identidade é protegida. Não registramos quem você é, seu IP ou se está logado.
195	          Evite incluir informações que possam te identificar na mensagem.
196	        </p>
197	      </div>
198	
199	      {/* Honeypot — sr-only, nunca visto por humanos */}
200	      <div className="sr-only" aria-hidden="true">
201	        <input
202	          tabIndex={-1}
203	          autoComplete="off"
204	          {...register('hp_field')}
205	        />
206	      </div>
207	
208	      {/* Categoria */}
209	      <div className="flex flex-col gap-1.5">
210	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
211	          Categoria <span className="text-red-500">*</span>
212	        </Label>
213	        <Select
214	          onValueChange={(v) => setValue('categoria', v as CategoriaOuvidoria, { shouldValidate: true })}
215	        >
216	          <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
217	            <SelectValue placeholder="Selecione uma categoria" />
218	          </SelectTrigger>
219	          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
220	            {CATEGORIAS_OUVIDORIA.map((cat) => (
221	              <SelectItem key={cat.value} value={cat.value}>
222	                {cat.label}
223	              </SelectItem>
224	            ))}
225	          </SelectContent>
226	        </Select>
227	        {errors.categoria && (
228	          <p className="text-xs text-red-500">{errors.categoria.message}</p>
229	        )}
230	      </div>
231	
232	      {/* Loja (opcional) */}
233	      <div className="flex flex-col gap-1.5">
234	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
235	          Loja relacionada <span className="text-muted-foreground font-normal">(opcional)</span>
236	        </Label>
237	        <Select onValueChange={(v) => setValue('loja_id', v)}>
238	          <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
239	            <SelectValue placeholder="Prefiro não informar" />
240	          </SelectTrigger>
241	          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
242	            <SelectItem value="__nao_informar">Prefiro não informar</SelectItem>
243	            {LOJAS_OUVIDORIA.map((loja) => (
244	              <SelectItem key={loja.id} value={String(loja.id)}>
245	                {loja.nome}
246	              </SelectItem>
247	            ))}
248	          </SelectContent>
249	        </Select>
250	      </div>
251	
252	      {/* Mensagem */}
253	      <div className="flex flex-col gap-1.5">
254	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
255	          Mensagem <span className="text-red-500">*</span>
256	        </Label>
257	        <textarea
258	          {...register('mensagem')}
259	          rows={6}
260	          maxLength={5000}
261	          placeholder="Descreva o ocorrido com detalhes..."
262	          className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
263	        />
264	        <div className="flex items-center justify-between">
265	          {errors.mensagem ? (
266	            <p className="text-xs text-red-500">{errors.mensagem.message}</p>
267	          ) : (
268	            <span />
269	          )}
270	          <span className="text-xs text-muted-foreground">
271	            {mensagemValue.length}/5.000
272	          </span>
273	        </div>
274	      </div>
275	
276	      {/* Senha de acompanhamento */}
277	      <div className="flex flex-col gap-1.5">
278	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
279	          Senha de acompanhamento <span className="text-red-500">*</span>
280	        </Label>
281	        <div className="relative">
282	          <Input
283	            {...register('senha')}
284	            type={mostrarSenha ? 'text' : 'password'}
285	            placeholder="Mínimo 4 caracteres"
286	            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
287	          />
288	          <button
289	            type="button"
290	            onClick={() => setMostrarSenha((v) => !v)}
291	            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
292	            aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
293	          >
294	            {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
295	          </button>
296	        </div>
297	        <p className="text-xs text-muted-foreground">
298	          Anote esta senha — ela não pode ser recuperada depois.
299	        </p>
300	        {errors.senha && (
301	          <p className="text-xs text-red-500">{errors.senha.message}</p>
302	        )}
303	      </div>
304	
305	      <Button
306	        type="submit"
307	        disabled={enviarDenuncia.isPending}
308	        className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2 mt-1"
309	      >
310	        {enviarDenuncia.isPending ? (
311	          <Loader2 className="h-4 w-4 animate-spin" />
312	        ) : (
313	          <Send className="h-4 w-4" />
314	        )}
