321	// ---------------------------------------------------------------------------
322	// Sub-componente: Acompanhamento de protocolo
323	// ---------------------------------------------------------------------------
324	
325	interface FormAcompanharProps {
326	  protocoloInicial?: string;
327	}
328	
329	function FormAcompanhar({ protocoloInicial }: FormAcompanharProps) {
330	  const [resultado, setResultado] = useState<ConsultaProtocoloResult | null>(null);
331	  const [consultaAtual, setConsultaAtual] = useState<{ protocolo: string; senha: string } | null>(null);
332	  const [respostaTexto, setRespostaTexto] = useState('');
333	  const [mostrarSenha, setMostrarSenha] = useState(false);
334	
335	  const consultarProtocolo = useConsultarProtocolo();
336	  const responderProtocolo = useResponderProtocolo();
337	
338	  const {
339	    register,
340	    handleSubmit,
341	    formState: { errors },
342	  } = useForm<ConsultaFormValues>({
343	    resolver: zodResolver(consultaSchema),
344	    defaultValues: { protocolo: protocoloInicial ?? '' },
345	  });
346	
347	  const onConsultar = handleSubmit(async (values) => {
348	    try {
349	      const res = await consultarProtocolo.mutateAsync({
350	        protocolo: values.protocolo.trim().toUpperCase(),
351	        senha: values.senha,
352	      });
353	      setResultado(res);
354	      if (res.ok) {
355	        setConsultaAtual({ protocolo: values.protocolo.trim().toUpperCase(), senha: values.senha });
356	      }
357	    } catch (err) {
358	      toast.error((err as Error).message ?? 'Erro ao consultar protocolo');
359	    }
360	  });
361	
362	  const onResponder = async () => {
363	    if (!consultaAtual || !respostaTexto.trim()) return;
364	    try {
365	      await responderProtocolo.mutateAsync({
366	        protocolo: consultaAtual.protocolo,
367	        senha: consultaAtual.senha,
368	        mensagem: respostaTexto.trim(),
369	      });
370	      setRespostaTexto('');
371	      // Reconsultar após resposta
372	      const res = await consultarProtocolo.mutateAsync(consultaAtual);
373	      setResultado(res);
374	      toast.success('Mensagem enviada');
375	    } catch (err) {
376	      toast.error((err as Error).message ?? 'Erro ao enviar mensagem');
377	    }
378	  };
379	
380	  return (
381	    <div className="flex flex-col gap-5">
382	      {/* Formulário de consulta */}
383	      <form onSubmit={onConsultar} className="flex flex-col gap-4">
384	        <div className="flex flex-col gap-1.5">
385	          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
386	            Protocolo
387	          </Label>
388	          <Input
389	            {...register('protocolo')}
390	            placeholder="Ex.: OUV-20240101-XXXX"
391	            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 font-mono uppercase"
392	          />
393	          {errors.protocolo && (
394	            <p className="text-xs text-red-500">{errors.protocolo.message}</p>
395	          )}
396	        </div>
397	
398	        <div className="flex flex-col gap-1.5">
399	          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
400	            Senha
401	          </Label>
402	          <div className="relative">
403	            <Input
404	              {...register('senha')}
405	              type={mostrarSenha ? 'text' : 'password'}
406	              placeholder="Sua senha de acompanhamento"
407	              className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
408	            />
409	            <button
410	              type="button"
411	              onClick={() => setMostrarSenha((v) => !v)}
412	              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
413	              aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
414	            >
415	              {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
416	            </button>
417	          </div>
418	          {errors.senha && (
419	            <p className="text-xs text-red-500">{errors.senha.message}</p>
420	          )}
421	        </div>
422	
423	        <Button
424	          type="submit"
425	          disabled={consultarProtocolo.isPending}
426	          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
427	        >
428	          {consultarProtocolo.isPending ? (
429	            <Loader2 className="h-4 w-4 animate-spin" />
430	          ) : null}
431	          {consultarProtocolo.isPending ? 'Consultando...' : 'Consultar protocolo'}
432	        </Button>
433	      </form>
434	
435	      {/* Resultado */}
436	      {resultado !== null && !resultado.ok && (
437	        <div className="rounded-2xl border border-red-200 dark:border-red-800/30 bg-red-50 dark:bg-red-900/10 p-4 text-sm text-red-600 dark:text-red-400">
438	          Protocolo ou senha incorretos.
439	        </div>
440	      )}
441	
442	      {resultado !== null && resultado.ok && (
443	        <div className="flex flex-col gap-4">
444	          {/* Cabeçalho da denúncia */}
445	          <GlassCard className="p-4 flex flex-col gap-3">
446	            <div className="flex flex-wrap items-center gap-2">
447	              <span className="font-mono text-sm font-bold text-[#57715B]">
448	                {resultado.denuncia.protocolo}
449	              </span>
450	              <CategoriaBadge categoria={resultado.denuncia.categoria} />
451	              <StatusBadge status={resultado.denuncia.status} />
452	            </div>
453	            <p className="text-xs text-muted-foreground">
454	              Registrada em{' '}
455	              {format(parseISO(resultado.denuncia.created_at), "dd/MM/yyyy 'às' HH:mm", {
456	                locale: ptBR,
457	              })}
458	            </p>
459	            <div className="border-t border-[#57715B]/10 pt-3">
460	              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
461	                Mensagem original
462	              </p>
463	              <p className="text-sm text-[#2D362E] dark:text-[#E6DCCF] whitespace-pre-wrap">
464	                {resultado.denuncia.mensagem}
465	              </p>
466	            </div>
467	          </GlassCard>
468	
469	          {/* Thread de mensagens */}
470	          {resultado.mensagens.length > 0 && (
471	            <div className="flex flex-col gap-3 py-2">
472	              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
473	                Conversas
474	              </p>
475	              <div className="flex flex-col gap-3">
476	                {resultado.mensagens.map((msg, i) => (
477	                  <MensagemBubble key={i} mensagem={msg} />
478	                ))}
479	              </div>
480	            </div>
481	          )}
482	
483	          {/* Responder */}
484	          {resultado.denuncia.status !== 'resolvida' &&
485	            resultado.denuncia.status !== 'arquivada' && (
486	              <div className="flex flex-col gap-2">
487	                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
488	                  Adicionar mensagem
489	                </p>
490	                <textarea
491	                  value={respostaTexto}
492	                  onChange={(e) => setRespostaTexto(e.target.value)}
493	                  rows={3}
494	                  placeholder="Adicione informações ou acompanhe o andamento..."
495	                  className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
496	                />
497	                <Button
498	                  type="button"
499	                  onClick={onResponder}
500	                  disabled={!respostaTexto.trim() || responderProtocolo.isPending}
501	                  className="self-end bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-9 px-4 gap-2 text-sm"
502	                >
503	                  {responderProtocolo.isPending ? (
504	                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
505	                  ) : (
506	                    <Send className="h-3.5 w-3.5" />
507	                  )}
508	                  Enviar
509	                </Button>
510	              </div>
511	            )}
512	        </div>
513	      )}
514	    </div>
515	  );
516	}
517	
