import js from "@eslint/js";
import globals from "globals";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import tseslint from "typescript-eslint";
import tsdoc from "eslint-plugin-tsdoc";
import eslintConfigPrettier from "eslint-config-prettier";
import boundaries from "eslint-plugin-boundaries";
import miaCoverage from "./eslint-rules/mia-coverage.js";

export default tseslint.config(
  { ignores: ["dist", ".claude/worktrees/**", "coverage/**", "scripts/**", "database_types.ts"] },
  {
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    files: ["**/*.{ts,tsx}"],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    plugins: {
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
      "tsdoc": tsdoc,
      "boundaries": boundaries,
      "mia-coverage": miaCoverage,
    },
    settings: {
      "boundaries/elements": [
        { type: "shared", pattern: "src/shared/*" },
        { type: "features", pattern: "src/features/*" },
        { type: "pages", pattern: "src/pages/*" },
        { type: "app", pattern: "src/app/*" },
      ],
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],
      "@typescript-eslint/no-unused-vars": "off",
      "@typescript-eslint/no-explicit-any": "off",
      "no-console": ["error", { allow: ["error"] }],
      "no-empty": ["error", { "allowEmptyCatch": true }],
      "tsdoc/syntax": "warn",
      // MIA Glass-Box coverage — warn global. Promovido pra error nas
      // features que JÁ TÊM skill typed no _registry.ts (vide override
      // abaixo). Política "expand inwards": cobertura sobe organicamente,
      // ESLint trava regressões nas áreas cobertas.
      "mia-coverage/require-data-mia-action": "warn",
      "mia-coverage/require-data-mia-field": "warn",
      "mia-coverage/require-data-mia-filter": "warn",
      "boundaries/element-types": [
        "error",
        {
          default: "disallow",
          rules: [
            { from: "shared", allow: ["shared"] },
            { from: "features", allow: ["shared", "features"] },
            { from: "pages", allow: ["shared", "features", "pages"] },
            { from: "app", allow: ["shared", "features", "pages", "app"] },
          ],
        },
      ],
    },
  }
  // ─── MIA coverage policy ───
  // Atualmente WARN global. Promoção pra ERROR planejada via override por
  // arquivo quando cada feature individual atingir cobertura >95% (botões
  // cosméticos marcados com data-mia-skip="true"). Roadmap: refinar
  // VerificacaoPerdas + DailyProductionForm + CashFlowEntryModal pra zero
  // warns, então promover esses paths via override. Hoje, override causou
  // 38 errors em buttons cosméticos não marcados — rollback até refinamento.
  //
  // CI pode usar custom check em PR scope-changed (script novo) que aplica
  // error só nos arquivos QUE A PR ALTEROU. Sem isso, override blanket fica
  // bloqueante demais nos diffs pequenos.
);

