// Local ESLint plugin — MIA glass-box coverage hints.
//
// Rules:
//   - mia-coverage/require-data-mia-action: warn quando <Button onClick={...}>
//     não tem data-mia-action. Aumenta cobertura organicamente.
//   - mia-coverage/require-data-mia-field: warn quando <Input id=X> não tem
//     data-mia-field=X.
//   - mia-coverage/require-data-mia-filter: warn quando <SelectTrigger> dentro
//     de <Select> não tem data-mia-filter.
//
// Severidade WARN (não error) — informa, não bloqueia merge. Quando coverage
// ficar > 90%, podemos subir pra error.
//
// Doc: docs/mia/ARCHITECTURE.md (Section 12.3 — ESLint coverage rule)

const hasJsxAttribute = (node, name) =>
  Array.isArray(node.attributes) && node.attributes.some((attr) =>
    attr.type === 'JSXAttribute' && attr.name?.name === name
  );

const getJsxAttribute = (node, name) =>
  Array.isArray(node.attributes) ? node.attributes.find((attr) =>
    attr.type === 'JSXAttribute' && attr.name?.name === name
  ) : null;

const tagNameOf = (node) => {
  if (!node?.name) return '';
  if (node.name.type === 'JSXIdentifier') return node.name.name;
  if (node.name.type === 'JSXMemberExpression') return node.name.property?.name ?? '';
  return '';
};

const requireActionRule = {
  meta: {
    type: 'suggestion',
    docs: { description: 'Adicione data-mia-action em Button com onClick' },
    schema: [],
  },
  create(context) {
    return {
      JSXOpeningElement(node) {
        const tag = tagNameOf(node);
        // Cobre Button, button, DropdownMenuItem, MenuItem (cliques principais)
        if (!['Button', 'button', 'DropdownMenuItem', 'MenuItem', 'CommandItem'].includes(tag)) return;
        // Só warn se tiver onClick (botões sem onClick podem ser display)
        if (!hasJsxAttribute(node, 'onClick')) return;
        // Já tem data-mia-action ou data-mia-skip → ok
        if (hasJsxAttribute(node, 'data-mia-action')) return;
        if (hasJsxAttribute(node, 'data-mia-skip')) return;
        // asChild — vai delegar pro filho (pode ter no Link/etc)
        if (hasJsxAttribute(node, 'asChild')) return;
        context.report({
          node,
          message: `<${tag}> com onClick sem \`data-mia-action="..."\`. Adicione pra MIA glass-box poder clicar (use data-mia-skip se intencional).`,
        });
      },
    };
  },
};

const requireFieldRule = {
  meta: {
    type: 'suggestion',
    docs: { description: 'Adicione data-mia-field em Input/Textarea' },
    schema: [],
  },
  create(context) {
    return {
      JSXOpeningElement(node) {
        const tag = tagNameOf(node);
        if (!['Input', 'Textarea', 'input', 'textarea'].includes(tag)) return;
        if (hasJsxAttribute(node, 'data-mia-field')) return;
        if (hasJsxAttribute(node, 'data-mia-skip')) return;
        // Pula inputs de busca/filtro inline (search bar do shadcn etc)
        const type = getJsxAttribute(node, 'type')?.value?.value;
        if (type === 'hidden' || type === 'file') return;
        // Pula sem id E sem name E sem placeholder (provavelmente decorativo)
        const hasId = hasJsxAttribute(node, 'id');
        const hasName = hasJsxAttribute(node, 'name');
        const hasPlaceholder = hasJsxAttribute(node, 'placeholder');
        if (!hasId && !hasName && !hasPlaceholder) return;
        context.report({
          node,
          message: `<${tag}> sem \`data-mia-field="..."\`. Adicione pra MIA glass-box poder preencher.`,
        });
      },
    };
  },
};

const requireFilterRule = {
  meta: {
    type: 'suggestion',
    docs: { description: 'Adicione data-mia-filter em SelectTrigger' },
    schema: [],
  },
  create(context) {
    return {
      JSXOpeningElement(node) {
        const tag = tagNameOf(node);
        if (tag !== 'SelectTrigger') return;
        if (hasJsxAttribute(node, 'data-mia-filter')) return;
        if (hasJsxAttribute(node, 'data-mia-skip')) return;
        context.report({
          node,
          message: `<SelectTrigger> sem \`data-mia-filter="..."\`. Adicione pra MIA glass-box poder selecionar opções.`,
        });
      },
    };
  },
};

export default {
  rules: {
    'require-data-mia-action': requireActionRule,
    'require-data-mia-field': requireFieldRule,
    'require-data-mia-filter': requireFilterRule,
  },
};

