import { render } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';

// ── Mocks ────────────────────────────────────────────────────────────────────
vi.mock('react-router-dom', () => ({
    useNavigate: () => vi.fn(),
    BrowserRouter: ({ children }: any) => <>{children}</>,
    MemoryRouter: ({ children }: any) => <>{children}</>,
}));

vi.mock('@tanstack/react-query', () => ({
    useQuery: () => ({
        data: undefined,
        isLoading: false,
        error: null,
    }),
    QueryClient: vi.fn().mockImplementation(() => ({
        defaultOptions: {},
    })),
    QueryClientProvider: ({ children }: any) => <>{children}</>,
}));

vi.mock('@/shared/hooks/use-mobile', () => ({
    useIsMobile: () => false,
}));

vi.mock('@/shared/hooks/usePermissions', () => ({
    usePermissions: () => ({ canViewGastos: () => true }),
}));

vi.mock('@/shared/ui/PermissionBlur', () => ({
    PermissionBlur: ({ children }: any) => <>{children}</>,
}));

vi.mock('@/features/financeiro', () => ({
    FinancialOverview: () => <div>FinancialOverview</div>,
    CategoryDashboard: () => <div>CategoryDashboard</div>,
}));

// ── Helper logic tests: filteredRecords and categories ───────────────────────

type FinancialRecord = {
    id: string;
    date: string;
    category_group: string;
    category_subgroup: string;
    amount: number;
    is_revenue: boolean;
};

const filterByYear = (records: FinancialRecord[], year: string) =>
    records.filter((r) => new Date(r.date).getFullYear().toString() === year);

const extractCategories = (records: FinancialRecord[]) => {
    const groups = new Set(records.map((r) => r.category_group));
    return Array.from(groups).sort();
};

const calcTotalRevenue = (records: FinancialRecord[]) =>
    records.reduce((acc, r) => (r.is_revenue ? acc + Number(r.amount) : acc), 0);

describe('Gastos — filteredRecords logic', () => {
    const records: FinancialRecord[] = [
        { id: '1', date: '2025-03-15', category_group: 'Insumos', category_subgroup: 'Farinha', amount: 5000, is_revenue: false },
        { id: '2', date: '2024-06-01', category_group: 'Pessoal', category_subgroup: 'Salários', amount: 20000, is_revenue: false },
        { id: '3', date: '2025-08-20', category_group: 'Receita', category_subgroup: 'Vendas', amount: 80000, is_revenue: true },
    ];

    it('filters records to only 2025', () => {
        const result = filterByYear(records, '2025');
        expect(result).toHaveLength(2);
    });

    it('filters records to only 2024', () => {
        const result = filterByYear(records, '2024');
        expect(result).toHaveLength(1);
        expect(result[0].category_group).toBe('Pessoal');
    });

    it('returns empty array when no records match year', () => {
        const result = filterByYear(records, '2023');
        expect(result).toHaveLength(0);
    });
});

describe('Gastos — categories extraction', () => {
    const records: FinancialRecord[] = [
        { id: '1', date: '2025-01-01', category_group: 'Insumos', category_subgroup: '', amount: 100, is_revenue: false },
        { id: '2', date: '2025-01-02', category_group: 'Pessoal', category_subgroup: '', amount: 200, is_revenue: false },
        { id: '3', date: '2025-01-03', category_group: 'Insumos', category_subgroup: '', amount: 50, is_revenue: false },
    ];

    it('returns unique sorted categories', () => {
        const result = extractCategories(records);
        expect(result).toEqual(['Insumos', 'Pessoal']);
    });

    it('returns empty array when no records', () => {
        expect(extractCategories([])).toHaveLength(0);
    });
});

describe('Gastos — totalRevenue calculation', () => {
    const records: FinancialRecord[] = [
        { id: '1', date: '2025-01-01', category_group: 'Receita', category_subgroup: '', amount: 50000, is_revenue: true },
        { id: '2', date: '2025-01-02', category_group: 'Custo', category_subgroup: '', amount: 10000, is_revenue: false },
        { id: '3', date: '2025-01-03', category_group: 'Receita', category_subgroup: '', amount: 30000, is_revenue: true },
    ];

    it('sums only revenue records', () => {
        expect(calcTotalRevenue(records)).toBe(80000);
    });

    it('returns 0 when no revenue records', () => {
        const noRevenue = records.filter((r) => !r.is_revenue);
        expect(calcTotalRevenue(noRevenue)).toBe(0);
    });
});

describe('Gastos — smoke render', () => {
    it('renders without crashing', async () => {
        const { default: Gastos } = await import('./Gastos.page');
        const { BrowserRouter } = await import('react-router-dom');
        render(
            <BrowserRouter>
                <Gastos />
            </BrowserRouter>,
        );
        expect(document.body).toBeTruthy();
    });
});

