/**
 * Testes co-located — Ouvidoria.page.tsx (painel das donas)
 *
 * Mocks:
 *  - useOuvidoriaAccess → controla gate de acesso
 *  - useOuvidoriaList   → lista de denúncias
 *  - useOuvidoriaUnreadCount → badge de não-lidas
 * Não toca o supabase real (já mockado globalmente em src/test/setup.ts)
 */

import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

// ── Mocks de model hooks ──────────────────────────────────────────────────────

vi.mock('../model/useOuvidoriaAccess', () => ({
  useOuvidoriaAccess: vi.fn(),
}));

vi.mock('../model/useOuvidoriaList', () => ({
  useOuvidoriaList: vi.fn(),
}));

vi.mock('../model/useOuvidoriaUnreadCount', () => ({
  useOuvidoriaUnreadCount: vi.fn(),
}));

// ── Mocks de shared UI que usa Radix/Portal ───────────────────────────────────

vi.mock('@/shared/ui/select', () => ({
  Select: ({ children }: any) => <div>{children}</div>,
  SelectContent: ({ children }: any) => <div>{children}</div>,
  SelectItem: ({ children }: any) => <div>{children}</div>,
  SelectTrigger: ({ children }: any) => <div>{children}</div>,
  SelectValue: () => <span />,
}));

vi.mock('@/shared/ui/table', () => ({
  Table: ({ children }: any) => <table>{children}</table>,
  TableBody: ({ children }: any) => <tbody>{children}</tbody>,
  TableCell: ({ children, ...props }: any) => <td {...props}>{children}</td>,
  TableHead: ({ children }: any) => <th>{children}</th>,
  TableHeader: ({ children }: any) => <thead>{children}</thead>,
  TableRow: ({ children, ...props }: any) => <tr {...props}>{children}</tr>,
}));

vi.mock('@/shared/ui/button', () => ({
  Button: ({ children, ...props }: any) => <button {...props}>{children}</button>,
}));

vi.mock('@/shared/ui/glass-card', () => ({
  GlassCard: ({ children, ...props }: any) => <div {...props}>{children}</div>,
}));

vi.mock('@/shared/ui/MommaPageLayout', () => ({
  MommaPageLayout: ({ children }: any) => <div>{children}</div>,
}));

vi.mock('@/shared/ui/TelemetryErrorBoundary', () => ({
  TelemetryErrorBoundary: ({ children }: any) => <>{children}</>,
}));

// date-fns — determinístico
vi.mock('date-fns', () => ({
  format: () => '16/06/2026',
  parseISO: (s: string) => new Date(s),
}));
vi.mock('date-fns/locale', () => ({ ptBR: {} }));

// ── Imports após mocks ────────────────────────────────────────────────────────

import { useOuvidoriaAccess } from '../model/useOuvidoriaAccess';
import { useOuvidoriaList } from '../model/useOuvidoriaList';
import { useOuvidoriaUnreadCount } from '../model/useOuvidoriaUnreadCount';

// ── Helpers ───────────────────────────────────────────────────────────────────

function makeQC() {
  return new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: 0 } },
  });
}

function renderPage() {
  // Importação dinâmica não é possível em testes síncronos com vi.mock —
  // importamos estático após os mocks serem configurados.
  const { default: OuvidoriaPage } = require('./Ouvidoria.page');
  return render(
    <QueryClientProvider client={makeQC()}>
      <MemoryRouter>
        <OuvidoriaPage />
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

// ── Testes ───────────────────────────────────────────────────────────────────

describe('OuvidoriaPage — gate de acesso', () => {
  beforeEach(() => {
    vi.mocked(useOuvidoriaUnreadCount).mockReturnValue({
      data: { denunciasNaoAbertas: 0, mensagensNaoLidas: 0, total: 0 },
      isLoading: false,
    } as any);
  });

  it('exibe "Acesso restrito" quando canView=false', () => {
    vi.mocked(useOuvidoriaAccess).mockReturnValue({ canView: false, isLoading: false });
    vi.mocked(useOuvidoriaList).mockReturnValue({ data: [], isLoading: false } as any);

    renderPage();

    expect(screen.getByText(/Acesso restrito/i)).toBeInTheDocument();
  });

  it('exibe skeleton quando isLoading=true', () => {
    vi.mocked(useOuvidoriaAccess).mockReturnValue({ canView: false, isLoading: true });
    vi.mocked(useOuvidoriaList).mockReturnValue({ data: [], isLoading: true } as any);

    const { container } = renderPage();

    // Skeleton usa animate-pulse — o documento deve renderizar sem crash
    expect(container).toBeTruthy();
  });

  it('exibe lista quando canView=true com denúncias', () => {
    vi.mocked(useOuvidoriaAccess).mockReturnValue({ canView: true, isLoading: false });
    vi.mocked(useOuvidoriaList).mockReturnValue({
      data: [
        {
          id: 'abc-123',
          protocolo: 'OUV-20260616-AAAA',
          categoria: 'assedio_moral',
          loja_id: 2,
          mensagem: 'Teste de denúncia',
          status: 'recebida',
          created_at: '2026-06-16T10:00:00Z',
          updated_at: '2026-06-16T10:00:00Z',
          ultima_resposta_em: null,
        },
      ],
      isLoading: false,
    } as any);

    renderPage();

    expect(screen.getByText('OUV-20260616-AAAA')).toBeInTheDocument();
  });

  it('exibe mensagem de vazio quando lista está vazia e canView=true', () => {
    vi.mocked(useOuvidoriaAccess).mockReturnValue({ canView: true, isLoading: false });
    vi.mocked(useOuvidoriaList).mockReturnValue({ data: [], isLoading: false } as any);

    renderPage();

    expect(screen.getByText(/Nenhuma denúncia registrada/i)).toBeInTheDocument();
  });
});

