 *
 * Mocks:
 *  - useEnviarDenuncia   → mutation de envio de denúncia
 *  - useConsultarProtocolo → mutation de consulta
 *  - useResponderProtocolo → mutation de resposta do denunciante
 * A página não requer autenticação; não usa StoreContext nem useOuvidoriaAccess.
 */

import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

// ── Mocks de model hooks ──────────────────────────────────────────────────────

vi.mock('../model/useEnviarDenuncia', () => ({
  useEnviarDenuncia: vi.fn(),
}));

vi.mock('../model/useConsultarProtocolo', () => ({
  useConsultarProtocolo: vi.fn(),
}));

vi.mock('../model/useResponderProtocolo', () => ({
  useResponderProtocolo: vi.fn(),
}));

// ── Mocks de shared UI ────────────────────────────────────────────────────────

vi.mock('@/shared/ui/select', () => ({
  Select: ({ children }: any) => <div>{children}</div>,
  SelectContent: ({ children }: any) => <div>{children}</div>,
  SelectItem: ({ children }: any) => <div>{children}</div>,
  SelectTrigger: ({ children }: any) => <div>{children}</div>,
  SelectValue: () => <span />,
}));

vi.mock('@/shared/ui/button', () => ({
